import numpy as np

def run_experiment(config):
    if "seed" not in config:
        raise ValueError("config requires key: seed")
    seed = int(config["seed"])
    n = int(config.get("n", 40))
    test_share = float(config.get("test_share", 0.25))
    lam = float(config.get("lam", 1.0))
    rng = np.random.default_rng(seed)
    perm = rng.permutation(n)
    n_test = max(1, int(round(n * test_share)))
    test_idx = perm[:n_test]
    train_idx = perm[n_test:]
    x = np.linspace(0.0, 1.0, n)
    y = 2.0 * x + rng.normal(0.0, 0.1, size=n)
    xt, yt = x[train_idx], y[train_idx]
    xv, yv = x[test_idx], y[test_idx]
    w = float((xt @ yt) / (xt @ xt + lam))
    rmse = float(np.sqrt(np.mean((w * xv - yv) ** 2)))
    return {"seed": seed, "n": n, "test_idx": [int(i) for i in test_idx],
            "w": w, "rmse": rmse}

def check_manifest(manifest):
    required = ("seed", "split", "metric", "versions")
    if not isinstance(manifest, dict):
        raise ValueError("manifest must be a dict")
    missing = [key for key in required if key not in manifest]
    if missing:
        raise ValueError("manifest fehlt: " + ", ".join(missing))
    return True

def repro_report(configs):
    table = {}
    for config in sorted(configs, key=lambda c: str(c["config_id"])):
        first = run_experiment(config)
        second = run_experiment(config)
        table[str(config["config_id"])] = {
            "score": float(first["rmse"]),
            "identical_rerun": first == second,
        }
    return table

def check_table(table):
    if not isinstance(table, dict) or not table:
        raise ValueError("Tabelle leer oder kein dict")
    for config_id, row in table.items():
        if not isinstance(row, dict) or "score" not in row or "identical_rerun" not in row:
            raise ValueError("Zeile unvollstaendig: " + str(config_id))
        if not isinstance(row["score"], float) or row["score"] < 0:
            raise ValueError("Score muss nichtnegativer float sein: " + str(config_id))
        if row["identical_rerun"] is not True:
            raise ValueError("Wiederholung nicht identisch: " + str(config_id))
    return True

